package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.BlockPos;import net.minecraft.server.level.*;import net.minecraft.world.phys.*;import java.util.*;
/** Server-only, bounded probes. Never creates/loads a chunk or alters the road. */
public final class NtTerrain {
 public static NtGeometry.Plan plan(ServerPlayer player,List<Vec3> points,NtGeometry.Settings cfg){var path=new NtGeometry.Path(points,cfg);var level=player.serverLevel();var view=new NtLoadedView(level);List<String> errors=new ArrayList<>(path.errors);List<Double> left=new ArrayList<>(),right=new ArrayList<>();double lift=0;
  int count=Math.max(1,(int)Math.ceil(path.length/.75)),columns=Math.max(2,(int)Math.ceil(cfg.width()));
  for(int i=0;i<=count;i++){var f=path.frame(path.length*i/count);for(int c=0;c<=columns;c++){Vec3 at=f.p().add(f.n().scale((c/(double)columns-.5)*cfg.width()));double ground=ground(player,at,errors,view);if(Double.isFinite(ground))lift=Math.max(lift,ground-f.p().y);}}
  lift=Math.max(0,lift);
  for(double station:path.stations){var f=path.frame(station);for(int sign:new int[]{-1,1}){Vec3 at=f.p().add(f.n().scale(path.half*sign));double foot=ground(player,at,errors,view);if(!Double.isFinite(foot))foot=f.p().y;double top=f.p().y+cfg.height()+.60+lift;if(top-foot<1||top-foot>24)add(errors,"A mast needs to be 1–24 blocks high. Add route points following the terrain.");if(!clearColumn(level,at.x,at.z,foot+.15,top+.25,view))add(errors,"A mast intersects terrain, a building or an unloaded chunk near "+BlockPos.containing(at).toShortString()+".");if(sign<0)left.add(foot);else right.add(foot);}}
  if(cfg.sides())for(int bay=0;bay<path.stations.length-1;bay++){double a=path.stations[bay],b=path.stations[bay+1];int rows=Math.max(2,(int)Math.ceil((b-a)/.75));for(int row=0;row<=rows;row++){var f=path.frame(a+(b-a)*row/rows);for(int sign:new int[]{-1,1}){double foot=ground(player,f.p().add(f.n().scale(path.half*sign)),errors,view);if(!Double.isFinite(foot))foot=f.p().y;if(sign<0)left.add(foot);else right.add(foot);}}}
  var plan=new NtGeometry.Plan(points,cfg,lift,left,right,errors);var panels=NtGeometry.panels(path,plan);
  for(var q:panels){var box=q.bounds();int minY=(int)Math.floor(box.minY),maxY=(int)Math.floor(box.maxY);if(minY<level.getMinBuildHeight()||maxY>=level.getMaxBuildHeight()){add(errors,"The roof lies outside this dimension's build height.");break;}var pos=BlockPos.containing(q.a());if(!level.getWorldBorder().isWithinBounds(pos)||!level.mayInteract(player,pos)||player.getServer()!=null&&player.getServer().isUnderSpawnProtection(level,pos,player)){add(errors,"Construction is not allowed at "+pos.toShortString()+".");break;}
   for(var p:BlockPos.betweenClosed((int)Math.floor(box.minX),minY,(int)Math.floor(box.minZ),(int)Math.floor(box.maxX),maxY,(int)Math.floor(box.maxZ))){var chunk=level.getChunkSource().getChunkNow(p.getX()>>4,p.getZ()>>4);if(chunk==null){add(errors,"Visit the complete route first: a required chunk is not loaded.");break;}var state=chunk.getBlockState(p);if(state.isAir())continue;for(var a:state.getCollisionShape(view,p).toAabbs())if(!(Math.abs(q.b().subtract(q.a()).cross(q.d().subtract(q.a())).normalize().y)<.01&&a.maxY+p.getY()<=Math.max(q.a().y,q.d().y)+.01)&&(Double.isFinite(NtGeometry.sweep(a.move(p),Vec3.ZERO,new NtGeometry.Triangle(q.a(),q.b(),q.c())))||Double.isFinite(NtGeometry.sweep(a.move(p),Vec3.ZERO,new NtGeometry.Triangle(q.a(),q.c(),q.d()))))){add(errors,"A net panel intersects an existing block near "+p.toShortString()+".");break;}}
   if(errors.size()>=8)break;
  }
  if(view.missing)add(errors,"A required neighbour chunk is not loaded. Visit the complete route first.");return new NtGeometry.Plan(points,cfg,lift,left,right,errors);
 }
 private static double ground(ServerPlayer player,Vec3 at,List<String> errors,NtLoadedView view){var l=player.serverLevel();int x=(int)Math.floor(at.x),z=(int)Math.floor(at.z);var chunk=l.getChunkSource().getChunkNow(x>>4,z>>4);if(chunk==null){add(errors,"Visit the complete route first: terrain is not loaded.");return Double.NaN;}BlockPos.MutableBlockPos p=new BlockPos.MutableBlockPos();for(int y=Math.min(l.getMaxBuildHeight()-1,(int)Math.floor(at.y+1));y>=Math.max(l.getMinBuildHeight(),(int)Math.floor(at.y)-12);y--){p.set(x,y,z);var state=chunk.getBlockState(p);if(state.isAir())continue;if(!state.getFluidState().isEmpty()){add(errors,"A support or road sample is in water near "+p.toShortString()+".");return Double.NaN;}for(var box:state.getCollisionShape(view,p).toAabbs())if(at.x-x>=box.minX&&at.x-x<=box.maxX&&at.z-z>=box.minZ&&at.z-z<=box.maxZ){double top=y+box.maxY;if(top<=at.y+1.05){if(!l.mayInteract(player,p)||player.getServer().isUnderSpawnProtection(l,p,player))add(errors,"No building permission near "+p.toShortString()+".");return top;}}}add(errors,"No solid ground within 12 blocks. Add route points at the road's real height.");return Double.NaN;}
 private static boolean clearColumn(ServerLevel l,double x,double z,double y0,double y1,NtLoadedView view){var chunk=l.getChunkSource().getChunkNow(((int)Math.floor(x))>>4,((int)Math.floor(z))>>4);if(chunk==null)return false;var box=new AABB(x-.13,y0,z-.13,x+.13,y1,z+.13);for(var p:BlockPos.betweenClosed((int)Math.floor(box.minX),(int)Math.floor(y0),(int)Math.floor(box.minZ),(int)Math.floor(box.maxX),(int)Math.floor(y1),(int)Math.floor(box.maxZ))){var c=l.getChunkSource().getChunkNow(p.getX()>>4,p.getZ()>>4);if(c==null)return false;for(var a:c.getBlockState(p).getCollisionShape(view,p).toAabbs())if(a.move(p).intersects(box))return false;}return true;}
 public static void add(List<String> errors,String error){if(errors.size()<8&&!errors.contains(error))errors.add(error);}
 public static int[] cost(NtGeometry.Plan p){var path=new NtGeometry.Path(p.points(),p.settings());double area=path.length*(p.settings().width()+.4+(p.settings().sides()?2*p.settings().height():0));return new int[]{path.stations.length*4,(int)Math.ceil(area/8),(int)Math.ceil(path.length/12)};}
}
